def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = False
    rich_opp_pressure = 0.0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 2:
                urgent_opp = True
            rich_opp_pressure = max(rich_opp_pressure, float(opp.get('daily_salary', 0)) * 0.75)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.35))

    scarcity = 1.0 - ((supply - 15.0) / 10.0)
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    base = DAILY_SALARY * (0.42 + 0.28 * scarcity)

    if hp <= 2 or no_water_days >= 2:
        emergency = DAILY_SALARY * (0.9 + 0.06 * scarcity)
        if prev_bids:
            emergency = max(emergency, max(prev_bids) + 2.0)
        return float(min(budget, emergency))

    if hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * (0.68 + 0.12 * scarcity))

    if prev_bids:
        top_prev = max(prev_bids)
        if supply <= 17.0:
            target = top_prev + 2.5
        elif supply <= 20.0:
            target = top_prev + 1.0
        else:
            target = top_prev * 0.92
        base = max(base, target)

    if urgent_opp and supply <= 18.0:
        base += 3.0

    if rich_opp_pressure > 0:
        base = max(base, min(rich_opp_pressure, DAILY_SALARY * 0.88))

    if supply >= 23.0 and hp >= 5 and no_water_days == 0:
        base = min(base, DAILY_SALARY * 0.48)

    reserve_floor = 0.0
    if hp >= 5 and no_water_days == 0:
        reserve_floor = budget * 0.55
    elif hp >= 3:
        reserve_floor = budget * 0.35
    else:
        reserve_floor = budget * 0.15

    bid = min(base, budget)
    if budget - bid < reserve_floor and hp > 2 and no_water_days < 2:
        bid = max(0.0, budget - reserve_floor)
        if prev_bids and supply <= 18.0:
            bid = max(bid, min(budget, max(prev_bids) + 0.5))

    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp and opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # Base cap: never bid more than we can afford.
    max_affordable_bid = max(0.0, budget)

    # If no opponents alive, conserve budget.
    if not alive_opponents:
        target = DAILY_SALARY * 0.35
        return min(max_affordable_bid, target)

    # Read yesterday bids to infer pressure.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    # If we have no trace info, fall back to a conservative strategy.
    if not prev_bids:
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.8
        else:
            target = DAILY_SALARY * 0.55
        return min(max_affordable_bid, target)

    highest_prev_bid = max(prev_bids)

    # Thresholds tuned to the example style: counter aggressively when others were near salary.
    high_pressure = DAILY_SALARY * 0.85
    mid_pressure = DAILY_SALARY * 0.60

    # Determine desired bid based on our condition.
    urgent = (hp <= 2) or (no_water_days >= 2)
    somewhat_urgent = (hp <= 3) or (no_water_days >= 1)

    # Also incorporate supply: if supply is tight, increase bids to secure allocation.
    # Use a safe discretization for indices.
    supply_bucket = int(max(0.0, min(1.0, (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY + 1e-9))))
    tight_multiplier = [0.95, 1.10][supply_bucket]

    if highest_prev_bid >= high_pressure:
        # Opponents were very aggressive yesterday; counter to prevent losing water.
        if urgent:
            target = DAILY_SALARY * 0.95
        elif somewhat_urgent:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.35
        target *= tight_multiplier
    elif highest_prev_bid >= mid_pressure:
        # Moderate aggression: match partially and adjust for our urgency.
        if urgent:
            target = max(highest_prev_bid + 1.0, DAILY_SALARY * 0.7)
        elif somewhat_urgent:
            target = max(highest_prev_bid * 0.9, DAILY_SALARY * 0.6)
        else:
            target = max(highest_prev_bid * 0.6, DAILY_SALARY * 0.5)
        target *= tight_multiplier
    else:
        # Low aggression: we can bid just enough to secure water; still scale with urgency.
        if urgent:
            target = DAILY_SALARY * 0.85
        elif somewhat_urgent:
            target = DAILY_SALARY * 0.65
        else:
            # Try to stay efficient: bid near a fraction of salary.
            target = DAILY_SALARY * 0.52
        # If supply is very high, slightly reduce.
        if supply >= float(MIN_SUPPLY) + (float(MAX_SUPPLY) - float(MIN_SUPPLY)) * 0.7:
            target *= 0.92
        target *= tight_multiplier

    # Ensure bid is at least a minimal positive amount when we need water.
    # Also avoid bidding negative.
    target = max(0.0, float(target))

    # If our hp is critically low, don't conserve.
    if hp <= 1:
        target = max(target, DAILY_SALARY * 0.95)

    return min(max_affordable_bid, target)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Extract yesterday's bids from traces
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        aggressive_threshold = DAILY_SALARY * 0.7  # ~98
        if highest_prev >= aggressive_threshold:
            # Opponent aggressive yesterday; maybe still aggressive
            if my_status['hp'] > 3:
                # Healthy, save money
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else:
                # Desperate, need water
                return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            # Opponent moderate; outbid slightly
            target = highest_prev + 2  # small increment
            max_bid = min(my_status['budget'], DAILY_SALARY * 0.8)
            return min(max_bid, target)

    # No history: bid based on health
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.85)
    return min(my_status['budget'], DAILY_SALARY * 0.5)
